svg.script:
(function () {
  const svg = document.getElementById('remote-svg');
  if (!svg) return;
  const buttons = svg.querySelectorAll('.remote-btn');
  const timers = new WeakMap();

  function triggerCorona(btn) {
    btn.classList.remove('is-pressed');
    // Force reflow so rapid repeated clicks restart the animation cleanly
    void btn.getBoundingClientRect();
    btn.classList.add('is-pressed');

    clearTimeout(timers.get(btn));
    const t = setTimeout(function () {
      btn.classList.remove('is-pressed');
    }, 650);
    timers.set(btn, t);

    svg.dispatchEvent(new CustomEvent('remote-button-press', {
      bubbles: true,
      detail: { id: btn.id, label: btn.getAttribute('aria-label') || btn.id }
    }));
  }

  buttons.forEach(function (btn) {
    btn.addEventListener('pointerdown', function (e) {
      e.stopPropagation();
      btn.classList.add('is-holding');
      triggerCorona(btn);
    });

    function release() {
      btn.classList.remove('is-holding');
    }

    btn.addEventListener('pointerup', release);
    btn.addEventListener('pointerleave', release);
    btn.addEventListener('pointercancel', release);

    btn.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        triggerCorona(btn);
      }
    });
  });

  // Public helper for external JS control
  svg.triggerRemoteButton = function (buttonId) {
    const target = svg.getElementById(buttonId);
    if (target) triggerCorona(target);
  };
})();
